'use strict';
(()=>{
let songs=[],connectionState='loading',connectionMessage='Đang tải kho nhạc từ Firebase…',returnFocus=null;
const $=s=>document.querySelector(s);
const esc=value=>String(value??'').normalize('NFC').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=v=>String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase();
const labels={underground:'Underground',soundcloud:'SoundCloud',dalab:'Da LAB',solo:'Solo','emcee-l':'Solo','emcee_l':'Solo','bai-rieng':'Solo',dsp:'Khác',other:'Chưa phân nhóm'};
const label=c=>labels[c]||c;
const collections={'tat-ca-bai-hat':{title:'Kho nhạc',category:'all'},'underground':{title:'Underground',category:'underground'},'soundcloud':{title:'SoundCloud',category:'soundcloud'},'da-lab-classics':{title:'Da LAB',category:'dalab'},'bai-rieng':{title:'Solo',category:'solo'}};
const aliases={'hop-tac-feat':'underground','archive-highlights':'soundcloud'};
let state={route:'',query:'',category:'all',year:'all',sort:'newest',page:1};
const mergeProfile=input=>{const base=window.VAULT_PROFILE_DEFAULTS||{};const p={...base,...(input||{})};for(const key of ['facts','roles','career','daLab','solo','fanNotes','social','skills','tags'])if(!Array.isArray(p[key]))p[key]=base[key]||[];return p;};
let profileState=mergeProfile(window.VAULT_REMOTE_PROFILE);
const profileURL=value=>{const v=String(value||'').trim();return /^https:\/\//.test(v)||v.startsWith('assets/')?v:'';};
const profileHref=value=>{const v=String(value||'').trim();return /^https:\/\//.test(v)||/^mailto:/.test(v)?v:'';};
window.addEventListener('profile-data',event=>{profileState=mergeProfile(event.detail);if(state.route==='ve-emcee-l')renderPage();});
const routePaths={'tat-ca-bai-hat':'/kho-nhac','underground':'/underground','soundcloud':'/soundcloud','da-lab-classics':'/da-lab','bai-rieng':'/solo','artist-chronology':'/dong-thoi-gian','loi-bai-hat-and-ghi-chu':'/ghi-chu','ve-emcee-l':'/ve-emcee-l','dieu-khoan-luu-tru':'/chinh-sach'};
const pathRoutes={'/':'tat-ca-bai-hat','/kho-nhac':'tat-ca-bai-hat','/tat-ca-bai-hat':'tat-ca-bai-hat','/underground':'underground','/soundcloud':'soundcloud','/da-lab':'da-lab-classics','/da-lab-classics':'da-lab-classics','/solo':'bai-rieng','/bai-rieng':'bai-rieng','/dong-thoi-gian':'artist-chronology','/artist-chronology':'artist-chronology','/ghi-chu':'loi-bai-hat-and-ghi-chu','/loi-bai-hat-and-ghi-chu':'loi-bai-hat-and-ghi-chu','/ve-emcee-l':'ve-emcee-l','/chinh-sach':'dieu-khoan-luu-tru','/dieu-khoan-luu-tru':'dieu-khoan-luu-tru'};
const routePath=route=>routePaths[route]||'/'+route;
const slugify=value=>normalize(value).replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'')||'ca-khuc';
const songPath=s=>'/bai-hat/'+slugify(s.title||'ca-khuc')+'--'+encodeURIComponent(s.id);
function songFromPath(){const raw=location.pathname.replace(/^\/bai-hat\/?/,'');let part;try{part=decodeURIComponent(raw);}catch{part=raw;}const marker=part.lastIndexOf('--');const id=marker>=0?part.slice(marker+2):part;return songs.find(s=>songPath(s)===location.pathname)||songs.find(s=>s.id===id)||songs.find(s=>s.id===part);}
function routeFromLocation(){const hash=location.hash.replace(/^#\/?/,'');if(hash){const pieces=hash.split('/');let target;if(pieces[0]==='bai-hat')target='/bai-hat/'+pieces.slice(1).join('/');else target=routePath(aliases[pieces[0]]||pieces[0]);history.replaceState({},'',target||'/kho-nhac');}const pathname=location.pathname.replace(/\/+$/,'')||'/';if(pathname==='/bai-hat'||pathname.startsWith('/bai-hat/'))return 'bai-hat';const route=pathRoutes[pathname]||pathname.slice(1)||'tat-ca-bai-hat';if(pathname!=='/'&&pathRoutes[pathname]&&routePath(route)!==pathname)history.replaceState({},'',routePath(route)+location.search);return route;}
function platformLinks(song){return Object.entries({YouTube:song.youtube,Spotify:song.spotify,'Apple Music':song.appleMusic,iTunes:song.itunes,SoundCloud:song.soundcloud}).filter(([,url])=>url);}
function platformButtons(song){const icons={YouTube:'youtube',Spotify:'spotify','Apple Music':'applemusic',iTunes:'itunes',SoundCloud:'soundcloud'};return platformLinks(song).map(([name,url])=>`<a class="platform-btn" href="${esc(url)}" target="_blank" rel="noopener noreferrer" title="${esc(name)} · mở tab mới" aria-label="Nghe ${esc(song.title)} trên ${esc(name)}, mở tab mới"><img src="assets/platforms/${icons[name]}.svg" alt="" width="20" height="20"></a>`).join('');}
function platformMarkup(song){return platformButtons(song)||'<p class="small-note">Chưa có liên kết nghe nhạc.</p>';}
let lyricCounter=0;
function lyricMarkup(s){const lyric=String(s.lyric||'');if(!lyric.trim())return '<section class="lyric-section"><h3>Lời bài hát</h3><p class="small-note">Chưa cập nhật lời bài hát.</p></section>';const long=lyric.length>900||lyric.split('\n').length>12,id='song-lyric-'+(++lyricCounter);return `<section class="lyric-section"><h3>Lời bài hát</h3><div id="${id}" class="song-lyric${long?' is-collapsed':''}">${esc(lyric)}</div>${long?`<button class="lyric-toggle" aria-expanded="false" aria-controls="${id}" data-lyric-toggle="${id}">Xem toàn bộ lời bài hát</button>`:''}</section>`;}
const soloCategories=new Set(['solo','emcee-l','emcee_l','bai-rieng']);
function categoryMatches(song,category){const actual=String(song.category||'').trim().toLowerCase().replace(/_/g,'-');return category==='solo'?soloCategories.has(actual):actual===category;}
function baseSongs(route=state.route){const c=collections[route];return c?songs.filter(s=>c.category==='all'||categoryMatches(s,c.category)):[];}
function visibleSongs(){const result=baseSongs().filter(s=>(state.category==='all'||s.category===state.category)&&(state.year==='all'||state.year==='unknown'&&s.year===null||s.year===Number(state.year))&&normalize([s.title,s.artist,s.lyric].join(' ')).includes(normalize(state.query.trim())));if(state.sort==='az')result.sort((a,b)=>a.title.localeCompare(b.title,'vi'));else result.sort((a,b)=>state.sort==='oldest'?(a.year??9999)-(b.year??9999):Number(b.featured)-Number(a.featured)||(b.year??0)-(a.year??0));return result;}
function card(s){return `<article class="song-card music-box"><div class="player-heading"><span class="player-category">${esc(label(s.category))}</span><span class="player-year">${s.year??'Chưa rõ năm'}</span></div><a class="cover player-deck" data-vinyl="${s.vinylColor||'pink'}" href="${esc(songPath(s))}" aria-label="Chi tiết ${esc(s.title)}"><span class="vinyl-spin orgel-disc rotating-carousel" aria-hidden="true"><span class="orgel-ring orgel-ring-outer"><span class="orgel-ring orgel-ring-inner"><span class="orgel-hub"><span class="orgel-spindle"><span></span></span></span></span></span></span><img class="vinyl-bow" src="assets/bow.svg" alt="" width="32" height="32"></a><div class="card-content"><h3><a class="card-detail-link" href="${esc(songPath(s))}">${esc(s.title)}</a></h3><p class="artist">${esc(s.artist||'Chưa cập nhật nghệ sĩ')}</p><div class="streaming-links" aria-label="Nền tảng nghe nhạc">${platformButtons(s)}</div></div></article>`;}
function emptyState(){if(connectionState==='loading')return '<div class="empty"><h3>Đang tải kho nhạc…</h3></div>';if(connectionState==='error'&&!songs.length)return `<div class="empty"><h3>Chưa tải được kho nhạc</h3><p>Vui lòng thử lại sau.</p><button class="primary" id="retry-load">Tải lại trang</button></div>`;if(!songs.length)return '<div class="empty"><h3>Kho nhạc chưa có bài hát</h3><p>Các ca khúc sẽ sớm được cập nhật.</p></div>';return '<div class="empty"><h3>Không có ca khúc phù hợp</h3><p>Thử từ khóa khác hoặc bỏ bớt bộ lọc.</p><button class="primary" id="reset-filters">Xóa tìm kiếm & bộ lọc</button></div>';}
const PAGE_SIZE=12;
function pagination(total){if(total<=1)return '';const pages=[...new Set([1,state.page-1,state.page,state.page+1,total])].filter(n=>n>=1&&n<=total).sort((a,b)=>a-b);return `<nav class="pagination" aria-label="Phân trang ca khúc"><button type="button" data-page="${state.page-1}" ${state.page===1?'disabled':''} aria-label="Trang trước">Trước</button>${pages.map((n,i)=>`${i&&n-pages[i-1]>1?'<span class="page-gap" aria-hidden="true">…</span>':''}<button type="button" data-page="${n}" aria-label="Trang ${n}" ${n===state.page?'aria-current="page"':''}>${n}</button>`).join('')}<button type="button" data-page="${state.page+1}" ${state.page===total?'disabled':''} aria-label="Trang sau">Sau</button><span class="page-summary">Trang ${state.page} / ${total}</span></nav>`;}
function renderResults(){const result=visibleSongs(),total=Math.max(1,Math.ceil(result.length/PAGE_SIZE));state.page=Math.max(1,Math.min(state.page,total));const start=(state.page-1)*PAGE_SIZE;$('#results-count').textContent=result.length?`${start+1}–${Math.min(start+PAGE_SIZE,result.length)} / ${result.length} ca khúc`:'0 ca khúc';$('#results').innerHTML=result.length?`<div class="grid">${result.slice(start,start+PAGE_SIZE).map(card).join('')}</div>${pagination(total)}`:emptyState();$('#clear-search').hidden=!state.query;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===state.category)));}
function collectionFilters(){const items=[['tat-ca-bai-hat','Tất cả'],['da-lab-classics','Da LAB'],['bai-rieng','Solo']];return `<nav class="collection-filters" aria-label="Lọc danh mục nhạc">${items.map(([route,title])=>`<a class="fold-filter" href="${routePath(route)}" ${state.route===route?'aria-current="page"':''}><span class="fold-corner fold-corner-top" aria-hidden="true"><span></span></span><span class="fold-corner fold-corner-bottom" aria-hidden="true"><span></span></span><span class="fold-fill" aria-hidden="true"></span><span class="fold-text">${title}</span></a>`).join('')}</nav>`;}
function renderCollection(){const c=collections[state.route];const years=[...new Set(songs.map(s=>s.year).filter(y=>y!==null))].sort((a,b)=>b-a);$('#page').innerHTML=`<div class="page-heading"><h2>${c.title}</h2><p>LONG'S VAULT</p></div><div class="toolbar"><div class="search"><label class="sr-only" for="search">Tìm ca khúc, nghệ sĩ, lời bài hát</label><input id="search" type="search" placeholder="Tìm ca khúc, nghệ sĩ, lời bài hát…" autocomplete="off" value="${esc(state.query)}"><button id="clear-search" aria-label="Xóa tìm kiếm" hidden>×</button></div><label class="sr-only" for="year">Năm phát hành</label><select id="year"><option value="all">Tất cả năm</option>${years.map(y=>`<option value="${y}">${y}</option>`).join('')}${songs.some(s=>s.year===null)?'<option value="unknown">Chưa rõ năm</option>':''}</select><label class="sr-only" for="sort">Sắp xếp</label><select id="sort"><option value="newest">Mới nhất</option><option value="oldest">Cũ nhất</option><option value="az">Tên A → Z</option></select></div>${collectionFilters()}<div class="result-line"><span id="results-count" role="status" aria-live="polite"></span></div><div id="results"></div>`;$('#year').value=state.year;$('#sort').value=state.sort;renderResults();}
function detailMarkup(s){return `<p class="eyebrow">LONG'S VAULT${s.year?' · '+s.year:''}</p><h2 class="dialog-title" id="dialog-title">${esc(s.title)}</h2><p class="dialog-meta">${esc(s.artist)} · ${esc(label(s.category))}</p>${s.date?`<p class="small-note">Ngày phát hành: ${esc(s.date)}</p>`:''}<div class="platforms">${platformMarkup(s)}</div>${lyricMarkup(s)}`;}
function detailPage(){const s=songFromPath();return s?`<article class="song-detail"><a class="detail-back" href="${routePath('tat-ca-bai-hat')}">← Trở về kho nhạc</a><div class="detail-shell"><div class="detail-art" data-vinyl="${esc(s.vinylColor||'pink')}"><span class="vinyl-spin orgel-disc rotating-carousel" aria-hidden="true"><span class="orgel-ring orgel-ring-outer"><span class="orgel-ring orgel-ring-inner"><span class="orgel-hub"><span class="orgel-spindle"><span></span></span></span></span></span></span><img class="vinyl-bow" src="assets/bow.svg" alt="" width="48" height="48"></div><div class="detail-copy">${detailMarkup(s)}</div></div></article>`:connectionState!=='live'?emptyState():`<div class="empty"><h2>Không tìm thấy ca khúc</h2><a href="${routePath('tat-ca-bai-hat')}">Trở về kho nhạc</a></div>`;}
function closeDialog(){if($('#song-dialog').open)$('#song-dialog').close();}
function openSong(id){const s=songs.find(s=>s.id===id);if(!s)return;returnFocus=document.activeElement;$('#dialog-content').innerHTML=detailMarkup(s)+`<p class="source-note"><a href="${esc(songPath(s))}">Mở trang riêng ↗</a></p>`;$('#song-dialog').showModal();document.body.style.overflow='hidden';}
function renderTimeline(){
 if(!songs.length)return emptyState();
 const years=[...new Set(songs.map(s=>s.year))].sort((a,b)=>(a??9999)-(b??9999));
 return `<article class="music-journey"><header class="journey-heading"><div><p class="eyebrow">NHỮNG GIAI ĐIỆU QUA NĂM THÁNG</p><h2>Dòng thời gian<span>Mỗi năm, một dấu ấn.</span></h2></div><p class="journey-total"><strong>${songs.length}</strong><span>ca khúc trong kho</span></p></header><nav class="year-jumps" aria-label="Chuyển đến năm">${years.map(y=>`<button type="button" data-timeline-year="${y??'unknown'}">${y??'Chưa rõ năm'}</button>`).join('')}</nav><div class="journey-track">${years.map(y=>{const group=songs.filter(s=>s.year===y);return `<section class="journey-year story-reveal" id="timeline-${y??'unknown'}" tabindex="-1"><header class="journey-year-label"><span class="journey-dot" aria-hidden="true"></span><h3>${y??'Chưa rõ năm'}</h3><span>${group.length} ca khúc</span></header><div class="journey-songs">${group.map((song,i)=>`<a class="journey-song" href="${esc(songPath(song))}"><span class="journey-number" aria-hidden="true">${String(i+1).padStart(2,'0')}</span><span class="journey-song-copy"><strong>${esc(song.title)}</strong><small>${esc(song.artist||'')}</small></span><span class="journey-category">${esc(label(song.category))}</span></a>`).join('')}</div></section>`;}).join('')}</div></article>`;
}
function renderNotes(){if(!songs.length)return emptyState();return `<div class="prose"><p class="eyebrow">LINER NOTES</p><h2>Mô tả & ghi chú</h2><p>Thông tin trong từng hồ sơ ca khúc.</p><ul class="notes-list">${songs.map(s=>`<li><a href="${esc(songPath(s))}">${esc(s.title)} ↗</a><small>${esc(s.meta||s.year||'')}</small></li>`).join('')}</ul></div>`;}
function renderArtist(){const p=profileState||mergeProfile();const image=profileURL(p.imageUrl)||'assets/profile/about.jpg';const social=(p.social||[]).filter(x=>x&&x.label&&x.value);return `<article class="artist-profile"><section class="profile-hero story-reveal"><div class="profile-portrait profile-frame"><img src="${esc(image)}" alt="${esc(p.imageAlt)}" width="1237" height="1749"><span class="frame-bow frame-bow-tl"><img src="assets/bow.svg" alt=""></span><span class="frame-bow frame-bow-tr"><img src="assets/bow.svg" alt=""></span><span class="frame-bow frame-bow-bl"><img src="assets/bow.svg" alt=""></span><span class="frame-bow frame-bow-br"><img src="assets/bow.svg" alt=""></span></div><div class="profile-intro"><p class="eyebrow">${esc(p.eyebrow)}</p><h2>${esc(p.stageName)}<span>${esc(p.headline).replace(/\n/g,'<br>')}</span></h2><p class="profile-lead">${esc(p.lead)}</p><div class="profile-tags">${p.tags.map(x=>`<span>${esc(x)}</span>`).join('')}</div><a class="primary" href="${routePath('tat-ca-bai-hat')}">Khám phá kho nhạc</a></div></section><blockquote class="profile-quote story-reveal">“${esc(p.quote)}”</blockquote><div class="profile-columns"><section class="story-reveal profile-section"><p class="eyebrow">01 / VỀ NGHỆ SĨ</p><h3>${esc(p.aboutTitle)}</h3><dl class="profile-facts">${p.facts.map(x=>`<div><dt>${esc(x.label)}</dt><dd>${esc(x.value)}</dd></div>`).join('')}</dl><p>${esc(p.bio)}</p></section><section class="story-reveal profile-section"><p class="eyebrow">02 / KỸ NĂNG & VAI TRÒ</p><h3>Từ giọng hát đến bản thu</h3><div class="profile-tags">${p.skills.map(x=>`<span>${esc(x)}</span>`).join('')}</div><ul class="profile-roles">${p.roles.map(x=>`<li>${esc(x.name)} <small>${esc(x.en)}</small></li>`).join('')}</ul></section></div><section class="story-reveal profile-section profile-career"><p class="eyebrow">03 / DẤU ẤN SỰ NGHIỆP</p><h3>Những chặng đường âm nhạc</h3><ol class="profile-timeline">${p.career.map(x=>`<li><span class="profile-time">${esc(x.time)}</span><div><h4>${esc(x.title)}</h4><p>${esc(x.text)}</p></div></li>`).join('')}</ol></section><div class="profile-columns"><section class="story-reveal profile-section"><p class="eyebrow">CÙNG DA LAB</p><h3>Những bài hát quen thuộc</h3><ul class="profile-releases">${p.daLab.map(x=>`<li><span>${esc(x.title)}${x.note?`<small>${esc(x.note)}</small>`:''}</span><time>${esc(x.year)}</time></li>`).join('')}</ul><a class="profile-text-link" href="${routePath('da-lab-classics')}">Xem kho nhạc Da LAB</a></section><section class="story-reveal profile-section"><p class="eyebrow">DẤU ẤN SOLO</p><h3>Một màu sắc riêng</h3><ul class="profile-releases">${p.solo.map(x=>`<li><span>${esc(x.title)}${x.note?`<small>${esc(x.note)}</small>`:''}</span><time>${esc(x.year)}</time></li>`).join('')}</ul><a class="profile-text-link" href="${routePath('bai-rieng')}">Xem kho Solo</a></section></div><section class="story-reveal profile-section profile-fan"><p class="eyebrow">04 / GÓC NHÌN CỦA FAN</p><h3>${esc(p.fanTitle)}</h3>${p.fanNotes.map(x=>`<p>${esc(x)}</p>`).join('')}<p class="profile-fan-note">${esc(p.fanNote)}</p></section><section class="story-reveal profile-section"><p class="eyebrow">05 / KẾT NỐI</p><h3>Theo dõi ${esc(p.stageName)}</h3><div class="profile-social">${social.map(x=>{const href=profileHref(x.url);return href?`<a href="${esc(href)}" target="_blank" rel="noopener noreferrer"><strong>${esc(x.label)}</strong><span>${esc(x.value)}</span></a>`:`<div><strong>${esc(x.label)}</strong><span>${esc(x.value)}</span></div>`;}).join('')}</div></section></article>`;}

function renderPolicy(){return `<div class="prose"><h2>Chính sách lưu trữ</h2><h3>Nguồn dữ liệu</h3><p>Toàn bộ danh sách ca khúc được đọc từ collection songs trên Firebase. Website không chứa danh sách bài hát mẫu. Khi mất kết nối sau khi đã tải, website có thể giữ dữ liệu nhận gần nhất để bạn tiếp tục xem.</p><h3>Nghe nhạc</h3><p>Website hiển thị các liên kết YouTube, Spotify, Apple Music, iTunes và SoundCloud được lưu trong từng hồ sơ. Những nền tảng chưa có liên kết sẽ không hiện nút nghe.</p><h3>Quyền tác giả</h3><p>Quyền đối với ca khúc và bản ghi thuộc chủ sở hữu tương ứng. Website không lưu trữ bản ghi âm.</p><h3>Quản trị</h3><p>Trang quản trị sử dụng Firebase Authentication và Cloud Firestore. Chỉ tài khoản được cấp quyền admin mới được ghi dữ liệu theo quy tắc Firestore.</p></div>`;}
let storyObserver;
function animateStories(){
 storyObserver?.disconnect();
 const nodes=document.querySelectorAll('.story-reveal');
 if(!nodes.length||!('IntersectionObserver' in window)||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 storyObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.classList.add('is-visible');storyObserver.unobserve(entry.target);}},{threshold:.06});
 nodes.forEach(node=>{node.classList.add('has-reveal');storyObserver.observe(node);});
}
function renderPage(){if(collections[state.route])renderCollection();else if(state.route==='bai-hat')$('#page').innerHTML=detailPage();else if(state.route==='artist-chronology')$('#page').innerHTML=renderTimeline();else if(state.route==='loi-bai-hat-and-ghi-chu')$('#page').innerHTML=renderNotes();else if(state.route==='ve-emcee-l')$('#page').innerHTML=renderArtist();else if(state.route==='dieu-khoan-luu-tru')$('#page').innerHTML=renderPolicy();else $('#page').innerHTML=`<div class="empty"><h2>Không tìm thấy trang</h2><a href="${routePath('tat-ca-bai-hat')}">Trở về kho nhạc</a></div>`;animateStories();document.title=($('#page h2')?.textContent||'Kho nhạc')+" — Long's Vault";}
function navigate(){closeDialog();const route=routeFromLocation();if(route==='content')return;const switchingCollection=!!(collections[state.route]&&collections[route]);const params=new URLSearchParams(location.search);state={route,query:switchingCollection?state.query:(collections[route]?params.get('q')||'':''),category:'all',year:switchingCollection?state.year:(collections[route]?params.get('year')||'all':'all'),sort:switchingCollection?state.sort:(collections[route]?params.get('sort')||'newest':'newest'),page:1};document.querySelectorAll('a[aria-current]').forEach(a=>a.removeAttribute('aria-current'));document.querySelectorAll('a[href]').forEach(a=>{try{if(new URL(a.href,location.href).pathname===routePath(route))a.setAttribute('aria-current','page');}catch{}});$('#intro').hidden=route!=='tat-ca-bai-hat';$('#navigation').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');renderPage();if(switchingCollection){document.querySelector('.collection-filters [aria-current=page]')?.focus({preventScroll:true});$('#page').scrollIntoView({block:'start'});}else window.scrollTo(0,0);}
function receiveData(event){const data=event.detail;connectionState=data.status;connectionMessage=data.message||'';if(data.status==='live')songs=data.songs;const searching=document.activeElement?.id==='search';renderPage();closeDialog();if(searching)$('#search')?.focus();}
window.addEventListener('vault-data',receiveData);
document.addEventListener('input',e=>{if(e.target.id==='search'){state.query=e.target.value;state.page=1;renderResults();}});
document.addEventListener('change',e=>{if(['year','sort'].includes(e.target.id)){state[e.target.id]=e.target.value;state.page=1;renderResults();}});
document.addEventListener('click',e=>{const link=e.target.closest('a[href]');if(link&&!link.target&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey){try{const url=new URL(link.href,location.href);if(url.origin===location.origin&&!url.pathname.startsWith('/admin')){e.preventDefault();history.pushState({},'',url.pathname+url.search);navigate();return;}}catch{}}const yearJump=e.target.closest('[data-timeline-year]');if(yearJump){const section=document.getElementById('timeline-'+yearJump.dataset.timelineYear);section?.classList.add('is-visible');section?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});section?.focus({preventScroll:true});}const toggle=e.target.closest('[data-lyric-toggle]');if(toggle){const expanded=toggle.getAttribute('aria-expanded')!=='true';document.getElementById(toggle.dataset.lyricToggle).classList.toggle('is-collapsed',!expanded);toggle.setAttribute('aria-expanded',String(expanded));toggle.textContent=expanded?'Thu gọn lời bài hát':'Xem toàn bộ lời bài hát';}const filter=e.target.closest('[data-filter]');if(filter){state.category=filter.dataset.filter;state.page=1;renderResults();}const song=e.target.closest('[data-song]');if(song)openSong(song.dataset.song);if(e.target.closest('#clear-search')){state.query='';state.page=1;$('#search').value='';renderResults();$('#search').focus();}if(e.target.closest('#reset-filters')){state.query='';state.year='all';state.category='all';state.page=1;renderCollection();$('#search').focus();}const pageButton=e.target.closest('[data-page]');if(pageButton&&!pageButton.disabled){state.page=Number(pageButton.dataset.page);renderResults();$('#page').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});document.querySelector('.pagination [aria-current=page]')?.focus({preventScroll:true});}if(e.target.closest('#retry-load'))location.reload();});
$('#menu-toggle').addEventListener('click',()=>$('#menu-toggle').setAttribute('aria-expanded',String($('#navigation').classList.toggle('open'))));$('#close-dialog').addEventListener('click',closeDialog);$('#song-dialog').addEventListener('click',e=>{if(e.target===$('#song-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});$('#song-dialog').addEventListener('close',()=>{document.body.style.overflow='';if(returnFocus?.isConnected)returnFocus.focus();});window.addEventListener('hashchange',navigate);window.addEventListener('popstate',navigate);navigate();if(window.VAULT_REMOTE)receiveData({detail:window.VAULT_REMOTE});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'search_archive',title:'Tìm ca khúc',description:'Tìm ca khúc trong dữ liệu Firebase đã tải và cập nhật giao diện.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.query!=='string'||Object.keys(input).some(k=>k!=='query'))throw new Error('query phải là chuỗi');if(!collections[state.route])throw new Error('Mở kho nhạc trước khi tìm');if(connectionState!=='live'&&!songs.length)throw new Error('Chưa tải được dữ liệu Firebase');state.query=input.query;state.page=1;$('#search').value=input.query;renderResults();return {results:visibleSongs().map(({id,title,artist,year,category})=>({id,title,artist,year,category}))};}})).catch(()=>{});}catch{}}
})();
